def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Recolor full uniform divider lines only when a perpendicular uniform line
    # intersects them; isolated uniform lines are content, as in demos 1 and 4.
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1]
    col_lines = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    for r in row_lines:
        if any(grid[r][c] == grid[0][c] for c in col_lines):
            out[r] = [2] * w
    for c in col_lines:
        if any(grid[r][c] == grid[0][c] for r in row_lines):
            for r in range(h):
                out[r][c] = 2
    return out", "exit_code": 0, "error": null}

